package com.badspell.server;

import com.badspell.content.*;
import com.badspell.formula.*;
import com.badspell.item.GloveFormulas;
import com.badspell.network.Packets;
import java.util.*;
import java.util.function.Consumer;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.Registries;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.event.RegisterGameTestsEvent;
import net.neoforged.neoforge.registries.DeferredRegister;

/** Actual Minecraft mechanics, not success-message assertions. Only registered in the GameTest run. */
public final class M1Tests {
    private static final DeferredRegister<Consumer<GameTestHelper>> FUNCTIONS=DeferredRegister.create(Registries.TEST_FUNCTION,"badspell");
    private static final List<String> names=new ArrayList<>();
    private static void test(String name,Consumer<GameTestHelper> test){names.add(name);FUNCTIONS.register(name,()->test);}
    private static ServerPlayer player(GameTestHelper helper){var p=net.neoforged.neoforge.common.util.FakePlayerFactory.get(helper.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"badspell-test"));var at=helper.absolutePos(new BlockPos(2,1,4));p.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);p.getInventory().clearContent();p.getPersistentData().putInt("badspell_focus",100);return p;}
    private static net.minecraft.nbt.CompoundTag tag(ItemStack stack){return stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();}
    static {
        test("m1_thermal_and_shield",h->{
            var p=player(h);var pig=h.spawn(net.minecraft.world.entity.EntityTypes.PIG,new BlockPos(3,1,3));pig.setHealth(10);var at=pig.blockPosition();var region=new Value.Region(SpellEffects.position(p.level(),at),0);long tick=p.level().getGameTime();
            for(String kind:List.of("heat","cold","shield")){
                var effect=new Value.Effect("badspell:"+kind,region,1,200,10,5);var action=SpellEffects.prepare(p,effect);h.assertTrue(action!=null,"Field prepares: "+kind);action.run();var fields=SpellFields.get(p.level()).forOwner(p.getUUID());var field=fields.getLast();
                var encoded=SpellFields.Field.CODEC.encodeStart(net.minecraft.nbt.NbtOps.INSTANCE,field).getOrThrow();h.assertTrue(SpellFields.Field.CODEC.parse(net.minecraft.nbt.NbtOps.INSTANCE,encoded).getOrThrow().equals(field),"Field persistence roundtrip");
                var arrow=kind.equals("shield")?h.spawn(net.minecraft.world.entity.EntityTypes.ARROW,new BlockPos(3,1,3)):null;SpellFields.advance(p.level(),p,field,(tick/20+1)*20);
                if(kind.equals("heat"))h.assertTrue(pig.getHealth()<10,"Heat damages a real entity");
                if(kind.equals("cold"))h.assertTrue(pig.hasEffect(net.minecraft.world.effect.MobEffects.SLOWNESS)&&pig.getTicksFrozen()>0,"Cold freezes and slows a real entity");
                if(arrow!=null)h.assertTrue(arrow.isRemoved(),"Shield removes an intersecting projectile");
            }h.succeed();
        });
        test("m1_monocle_and_stale_glove",h->{var p=player(h);var monocle=new ItemStack(ModItems.ARCANE_MONOCLE.get());p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD,monocle);p.getPersistentData().putInt("badspell_focus",50);ToolActions.scan(p);h.assertTrue(p.getPersistentData().getIntOr("badspell_focus",0)==49,"Enabled worn monocle costs one FK per scan");CustomData.update(DataComponents.CUSTOM_DATA,monocle,t->t.putInt("badspell_intensity",0));ToolActions.scan(p);h.assertTrue(p.getPersistentData().getIntOr("badspell_focus",0)==49,"Disabled monocle costs no focus");
            var glove=new ItemStack(ModItems.RUNE_GLOVE_Q3.get());try{GloveFormulas.importSnapshot(glove,ExampleFormulas.light(p.getUUID()),p.getUUID());GloveFormulas.backup(p,glove);var stale=glove.copy();GloveFormulas.cycle(glove,1,p.getUUID());GloveFormulas.backup(p,glove);h.assertTrue(!GloveFormulas.current(p,stale),"Old device revision is detected");h.assertTrue(GloveFormulas.restore(p,stale)&&GloveFormulas.current(p,stale),"Player mirror restores a stale device");h.assertTrue(GloveFormulas.selected(stale)==1,"Restore includes active slot");}catch(java.io.IOException error){throw new IllegalStateException(error);}h.succeed();
        });
        test("m1_interval_renews_expired_light",h->{var p=player(h);p.getInventory().setItem(0,new ItemStack(ModItems.FIELD_CELL.get()));var at=h.absolutePos(new BlockPos(3,2,3));var base=ExampleFormulas.light(p.getUUID());var nodes=new ArrayList<>(base.nodes());nodes.removeIf(n->n.id().equals("impulse")||n.id().equals("light"));nodes.add(new Formula.Node("impulse","badspell:interval",0,0,Map.of("ticks",new Value.Number(20))));nodes.add(new Formula.Node("light","badspell:light",0,0,Map.of("strength",new Value.Number(3),"duration_ticks",new Value.Number(20))));nodes.add(new Formula.Node("limit","badspell:limit",0,0,Map.of("count",new Value.Number(2))));var edges=new ArrayList<>(base.edges());edges.removeIf(e->e.to().equals("activate")&&e.port().equals("trigger"));edges.add(new Formula.Edge("impulse","limit","trigger"));edges.add(new Formula.Edge("limit","activate","trigger"));var f=new Formula(UUID.randomUUID(),p.getUUID(),1,"repeat",nodes,edges,base.output(),100);var context=SpellEffects.context(p,at,p.level().getGameTime());var event=new FormulaEngine(RuneRegistry.standard()).plan(f,context).event();h.assertTrue(MagicActions.execute(p,f,context)==ActivationService.Result.APPLIED,"First pulse succeeds");try{ScheduledSpells.add(p,f,context,event,true);}catch(java.io.IOException e){throw new IllegalStateException(e);}h.runAfterDelay(20,()->{ScheduledSpells.tick(p);h.assertTrue(tag(p.getInventory().getItem(0)).getIntOr("badspell_fl",100)==96,"Two pulses each pay one light FL and one sensor FL");h.assertTrue(p.getPersistentData().getListOrEmpty("badspell_schedules").isEmpty(),"Limit terminates after two actual pulses");h.succeed();});});
        test("m1_schedule_pauses_for_energy",h->{var p=player(h);var cell=new ItemStack(ModItems.FIELD_CELL.get());CustomData.update(DataComponents.CUSTOM_DATA,cell,t->t.putInt("badspell_fl",0));p.getInventory().setItem(0,cell);var at=h.absolutePos(new BlockPos(3,2,3));var base=ExampleFormulas.light(p.getUUID());var nodes=new ArrayList<>(base.nodes());nodes.add(new Formula.Node("delay","badspell:delay",0,0,Map.of("ticks",new Value.Number(5))));var edges=new ArrayList<>(base.edges());edges.removeIf(e->e.to().equals("activate")&&e.port().equals("trigger"));edges.add(new Formula.Edge("impulse","delay","trigger"));edges.add(new Formula.Edge("delay","activate","trigger"));var f=new Formula(UUID.randomUUID(),p.getUUID(),1,"pause",nodes,edges,base.output(),100);var context=SpellEffects.context(p,at,p.level().getGameTime());try{ScheduledSpells.add(p,f,context,new FormulaEngine(RuneRegistry.standard()).plan(f,context).event(),false);}catch(java.io.IOException e){throw new IllegalStateException(e);}h.runAfterDelay(10,()->{ScheduledSpells.tick(p);h.assertTrue(p.getPersistentData().getListOrEmpty("badspell_schedules").size()==1,"Insufficient energy pauses rather than consuming the job");p.getInventory().setItem(0,new ItemStack(ModItems.FIELD_CELL.get()));});h.runAfterDelay(35,()->{ScheduledSpells.tick(p);h.assertTrue(tag(p.getInventory().getItem(0)).getIntOr("badspell_fl",100)==70,"Paused job resumes with exactly one debit");h.succeed();});});
        test("m1_claim_veto",h->{var p=player(h);p.getInventory().setItem(0,new ItemStack(ModItems.FIELD_CELL.get()));var at=h.absolutePos(new BlockPos(3,2,3));java.util.function.Consumer<net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock> veto=event->{if(event.getEntity().getUUID().equals(p.getUUID())&&event.getPos().equals(at))event.setCanceled(true);};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(veto);try{var result=MagicActions.execute(p,ExampleFormulas.light(p.getUUID()),SpellEffects.context(p,at,p.level().getGameTime()));h.assertTrue(result==ActivationService.Result.DENIED,"Official protection event can veto a spell");h.assertTrue(tag(p.getInventory().getItem(0)).getIntOr("badspell_fl",100)==100,"Veto consumes no energy");}finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(veto);}h.succeed();});
        test("m1_quality_slots",h->{var p=player(h);for(var item:List.of(ModItems.RUNE_GLOVE.get(),ModItems.RUNE_GLOVE_Q2.get(),ModItems.RUNE_GLOVE_Q3.get())){
            var glove=new ItemStack(item);int capacity=GloveFormulas.capacity(glove);try{for(int slot=0;slot<capacity;slot++){GloveFormulas.importSnapshot(glove,ExampleFormulas.light(p.getUUID()),p.getUUID());GloveFormulas.cycle(glove,1,p.getUUID());}for(int slot=0;slot<capacity;slot++)h.assertTrue(GloveFormulas.occupied(glove,slot),"Every quality slot retains its formula");GloveFormulas.backup(p,glove);h.assertTrue(p.getPersistentData().getCompoundOrEmpty("badspell_glove_backups").keySet().size()>0,"Player mirror stored");}catch(java.io.IOException e){throw new IllegalStateException(e);}}
            h.succeed();});
        test("m1_regeneration_and_push",h->{var p=player(h);var healed=h.spawn(net.minecraft.world.entity.EntityTypes.PIG,new BlockPos(3,1,4));healed.setHealth(2);p.getInventory().setItem(0,new ItemStack(ModItems.FIELD_CELL_Q3.get()));var pos=SpellEffects.position(p.level(),p.blockPosition());
            var f=new Formula(UUID.randomUUID(),p.getUUID(),1,"heal",List.of(new Formula.Node("self","badspell:target_entity",0,0,Map.of()),new Formula.Node("heal","badspell:heal",0,0,Map.of("points",new Value.Number(2))),new Formula.Node("pulse","badspell:impulse",0,0,Map.of()),new Formula.Node("activate","badspell:activate",0,0,Map.of())),List.of(new Formula.Edge("pulse","self","trigger"),new Formula.Edge("self","heal","target"),new Formula.Edge("heal","activate","effect"),new Formula.Edge("pulse","activate","trigger")),"activate",100);
            h.assertTrue(MagicActions.execute(p,f,new RuneRegistry.Context(SpellEffects.position(p.level(),healed.blockPosition()),p.level().getGameTime(),new Value.Entity(healed.getUUID(),SpellEffects.position(p.level(),healed.blockPosition())),new Value.Vector(0,0,1000),Map.of()))==ActivationService.Result.APPLIED,"Healing formula executes");h.assertTrue(tag(p.getInventory().getItem(0)).getIntOr("badspell_fl",600)==570,"Healing costs 30 FL");h.assertTrue(MagicActions.execute(p,f,new RuneRegistry.Context(SpellEffects.position(p.level(),healed.blockPosition()),p.level().getGameTime(),new Value.Entity(healed.getUUID(),SpellEffects.position(p.level(),healed.blockPosition())),new Value.Vector(0,0,1000),Map.of()))==ActivationService.Result.DENIED,"Regeneration cannot stack");h.assertTrue(tag(p.getInventory().getItem(0)).getIntOr("badspell_fl",600)==570,"Rejected healing does not spend FL");
            var pig=healed;var effect=new Value.Effect("badspell:push",new Value.Region(SpellEffects.position(p.level(),pig.blockPosition()),0),1,1,45,12,new Value.Entity(pig.getUUID(),SpellEffects.position(p.level(),pig.blockPosition())),new Value.Vector(0,600,300),new Value.Event(0));var action=SpellEffects.prepare(p,effect);h.assertTrue(action!=null,"Push prepares an eligible entity");action.run();h.assertTrue(pig.getDeltaMovement().y>.5,"Real entity receives upward velocity");h.runAfterDelay(55,()->{h.assertTrue(healed.getHealth()>2,"Regeneration restores actual health");h.succeed();});});
        test("m1_area_light",h->{var p=player(h);var at=h.absolutePos(new BlockPos(3,3,3));var center=SpellEffects.position(p.level(),at);var region=new Value.Region(center,1,Value.Shape.SPHERE,List.of(),new Value.Vector(0,0,1000),0);var effect=new Value.Effect("badspell:light",region,3,600,60,5);var action=SpellEffects.prepare(p,effect);h.assertTrue(action!=null,"Spherical light prepares all target cells");action.run();h.assertTrue(SpellEffects.positions(region).size()==7,"Radius-one sphere has seven cells");h.succeedWhen(()->{p.level().getChunkSource().pollTask();p.level().getChunkSource().getLightEngine().tryScheduleUpdate();try{Thread.sleep(1);}catch(InterruptedException e){Thread.currentThread().interrupt();}h.assertTrue(p.level().getBrightness(net.minecraft.world.level.LightLayer.BLOCK,at.above())==3,"The upper sphere cell really emits light");});});
        test("m1_physical_runes",h->{var p=player(h);var at=h.absolutePos(new BlockPos(2,1,2));p.level().setBlockAndUpdate(at,Blocks.STONE.defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ModItems.RUNE_CHISEL.get()));var base=ExampleFormulas.light(p.getUUID());var nodes=new ArrayList<Formula.Node>();for(int i=0;i<base.nodes().size();i++){var n=base.nodes().get(i);nodes.add(new Formula.Node(n.id(),n.rune(),i%4*154,i/4*100,n.parameters()));}var formula=new Formula(UUID.randomUUID(),p.getUUID(),1,"engraved",nodes,base.edges(),base.output(),100);
            try{ToolActions.handle(p,new Packets.BoardAction(0,at,Direction.SOUTH.ordinal(),FormulaCodec.encode(formula)));}catch(java.io.IOException e){throw new IllegalStateException(e);}var board=RuneBoards.get(p.level()).find(at,Direction.SOUTH.ordinal());h.assertTrue(board!=null&&board.formula().nodes().size()==5,"Physical field stored on selected face");h.assertTrue(RuneBoards.get(p.level()).find(at,Direction.NORTH.ordinal())==null,"Other faces remain independent");h.assertTrue(p.getMainHandItem().getDamageValue()==5,"Five rune confirmations use five durability");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ModItems.RESONANCE_FORK.get()));CustomData.update(DataComponents.CUSTOM_DATA,p.getMainHandItem(),t->t.putInt("badspell_mode",1));ToolActions.useBlock(p,InteractionHand.MAIN_HAND,at,Direction.SOUTH,1);h.assertTrue(p.getMainHandItem().getDamageValue()==0,"No energy means no successful fork use");p.getInventory().setItem(1,new ItemStack(ModItems.FIELD_CELL.get()));ToolActions.useBlock(p,InteractionHand.MAIN_HAND,at,Direction.SOUTH,1);h.assertTrue(p.getMainHandItem().getDamageValue()==1,"Successful physical activation uses one fork durability");h.assertTrue(tag(p.getInventory().getItem(1)).getIntOr("badspell_fl",100)==70,"Physical field uses the same 30 FL formula");p.level().setBlockAndUpdate(at,Blocks.AIR.defaultBlockState());h.assertTrue(RuneBoards.get(p.level()).find(at,Direction.SOUTH.ordinal())==null,"Real block replacement invalidates physical runes");h.succeed();});
        test("m1_library",h->{var p=player(h);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ModItems.FORMULA_BOOK.get()));MagicActions.openBook(p,InteractionHand.MAIN_HAND);UUID original;try{original=FormulaCodec.decode(tag(p.getMainHandItem()).getByteArray("badspell_formula").orElseThrow()).id();}catch(java.io.IOException e){throw new IllegalStateException(e);}FormulaLibrary.handle(p,new Packets.LibraryAction(0,1,new UUID(0,0),"Second formula","",0));h.assertTrue(p.getPersistentData().getCompoundOrEmpty(FormulaLibrary.KEY).keySet().size()==2,"Private library retains both formulas");h.assertTrue(tag(p.getMainHandItem()).getIntOr("badspell_ink",0)==59,"Creating starter graph consumes five writing points");h.runAfterDelay(3,()->{FormulaLibrary.handle(p,new Packets.LibraryAction(0,2,original,"","",0));try{h.assertTrue(FormulaCodec.decode(tag(p.getMainHandItem()).getByteArray("badspell_formula").orElseThrow()).id().equals(original),"Library switches back without replacing identity");}catch(java.io.IOException e){throw new IllegalStateException(e);}h.succeed();});});
        test("m1_local_transport",h->{var p=player(h);var a=h.absolutePos(new BlockPos(2,1,2));var b=h.absolutePos(new BlockPos(4,1,2));p.level().setBlockAndUpdate(a,Blocks.BARREL.defaultBlockState());p.level().setBlockAndUpdate(b,Blocks.BARREL.defaultBlockState());var from=(net.minecraft.world.Container)p.level().getBlockEntity(a);var to=(net.minecraft.world.Container)p.level().getBlockEntity(b);from.setItem(0,new ItemStack(Items.DIAMOND,8));for(int i=0;i<to.getContainerSize();i++)to.setItem(i,new ItemStack(Items.COBBLESTONE,64));var region=new Value.Region(SpellEffects.position(p.level(),a),0);var vector=new Value.Vector(2000,0,0);var bind=new Value.Effect("badspell:bind",region,1,1200,30,8,null,vector,new Value.Event(0));var action=SpellEffects.prepare(p,bind);h.assertTrue(action!=null,"Local binding prepares");action.run();var transfer=new Value.Effect("badspell:transfer",region,3,1,15,8,null,vector,new Value.Event(0));h.assertTrue(SpellEffects.prepare(p,transfer)==null&&from.getItem(0).getCount()==8,"Full output refuses without loss");to.setItem(0,ItemStack.EMPTY);action=SpellEffects.prepare(p,transfer);h.assertTrue(action!=null,"Bound inventories can transfer");action.run();h.assertTrue(from.getItem(0).getCount()==5&&to.getItem(0).getCount()==3,"Exactly three real items moved");var seal=new Value.Effect("badspell:seal",new Value.Region(SpellEffects.position(p.level(),b),0),1,200,20,8);action=SpellEffects.prepare(p,seal);h.assertTrue(action!=null,"Seal prepares");action.run();h.assertTrue(WorldBindings.sealed(p.level(),b,UUID.randomUUID())&&!WorldBindings.sealed(p.level(),b,p.getUUID()),"Seal distinguishes owner and strangers");h.succeed();});
        test("m1_deferred_cast",h->{var p=player(h);p.getInventory().setItem(0,new ItemStack(ModItems.FIELD_CELL.get()));var at=h.absolutePos(new BlockPos(3,2,3));var base=ExampleFormulas.light(p.getUUID());var nodes=new ArrayList<>(base.nodes());nodes.add(new Formula.Node("delay","badspell:delay",0,0,Map.of("ticks",new Value.Number(10))));var edges=new ArrayList<>(base.edges());edges.removeIf(e->e.to().equals("activate")&&e.port().equals("trigger"));edges.add(new Formula.Edge("impulse","delay","trigger"));edges.add(new Formula.Edge("delay","activate","trigger"));var formula=new Formula(UUID.randomUUID(),p.getUUID(),1,"delay",nodes,edges,base.output(),100);var context=SpellEffects.context(p,at,p.level().getGameTime());var event=new FormulaEngine(RuneRegistry.standard()).plan(formula,context).event();h.assertTrue(MagicActions.execute(p,formula,context)==ActivationService.Result.WAITING,"Delay starts without spending");h.assertTrue(tag(p.getInventory().getItem(0)).getIntOr("badspell_fl",100)==100,"No initial debit");try{ScheduledSpells.add(p,formula,context,event,false);}catch(java.io.IOException e){throw new IllegalStateException(e);}h.runAfterDelay(20,()->{ScheduledSpells.tick(p);h.assertTrue(tag(p.getInventory().getItem(0)).getIntOr("badspell_fl",100)==70,"Deferred job spent exactly once");h.assertTrue(p.getPersistentData().getListOrEmpty("badspell_schedules").isEmpty(),"One-shot job terminates");h.succeed();});});
        test("m1_upgrade_preserves_slots",h->{var p=player(h);var at=h.absolutePos(new BlockPos(2,1,2));p.level().setBlockAndUpdate(at,ModContent.STATIONS.get("engraving_station").get().defaultBlockState());var station=(com.badspell.production.StationBlockEntity)p.level().getBlockEntity(at);station.claim(p);var glove=new ItemStack(ModItems.RUNE_GLOVE.get());try{GloveFormulas.cycle(glove,1,p.getUUID());GloveFormulas.importSnapshot(glove,ExampleFormulas.light(p.getUUID()),p.getUUID());GloveFormulas.backup(p,glove);}catch(java.io.IOException e){throw new IllegalStateException(e);}station.setItem(0,glove);station.setItem(1,new ItemStack(ModContent.item("precision_coil"),2));station.setItem(2,new ItemStack(ModContent.item("arcane_alloy"),2));station.setItem(3,new ItemStack(ModContent.item("stabilizer_seal")));station.setItem(6,new ItemStack(ModItems.FIELD_CELL_Q2.get()));station.setItem(11,new ItemStack(ModContent.item("cell_adapter")));h.runAfterDelay(120,()->{var result=station.getItem(7);h.assertTrue(result.is(ModItems.RUNE_GLOVE_Q2.get()),"Actual station produces Q2 glove");h.assertTrue(GloveFormulas.capacity(result)==8&&GloveFormulas.occupied(result,1),"Upgrade preserves selected slot and snapshot");h.assertTrue(station.getItem(0).isEmpty()&&station.data.get(2)==200,"Upgrade consumes glove and exactly 100 FL");h.succeed();});});
        test("m1_compass_immutable_location",h->{var p=player(h);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ModItems.FIELD_COMPASS.get()));p.setShiftKeyDown(true);var a=h.absolutePos(new BlockPos(2,1,2));var b=a.east();ToolActions.useBlock(p,InteractionHand.MAIN_HAND,a,Direction.UP,2);var first=p.getMainHandItem().copy();ToolActions.useBlock(p,InteractionHand.MAIN_HAND,b,Direction.UP,2);h.assertTrue(!tag(first).read("badspell_signature",UUIDUtil.CODEC).equals(tag(p.getMainHandItem()).read("badspell_signature",UUIDUtil.CODEC)),"Rebinding creates a new signature ID");h.assertTrue(tag(first).getIntOr("badspell_x",0)==a.getX(),"An existing copied signature cannot move");h.succeed();});
    }
    public static void register(IEventBus bus){FUNCTIONS.register(bus);bus.addListener(M1Tests::tests);}
    private static void tests(RegisterGameTestsEvent event){var env=event.registerEnvironment(Identifier.fromNamespaceAndPath("badspell","m1_environment"));for(String name:names){var id=Identifier.fromNamespaceAndPath("badspell",name);event.registerTest(id,new FunctionGameTestInstance(ResourceKey.create(Registries.TEST_FUNCTION,id),new TestData<>(env,Identifier.fromNamespaceAndPath("badspell","test_room"),1000,0,true)));}}
}
